sp_css.css:
ul, ol {
	list-style-position: outside !important;
}

.beware {
    background-color: RGB(var(--now-alert--info--background-color,var(--now-messaging--primary_info--background-color,var(--now-color_alert--info-0,195,221,240))));
    border-color: RGB(var(--now-alert--info--border-color,var(--now-messaging--primary_info--border-color,var(--now-color_alert--info-1,104,171,218))));
    color: RGB(var(--now-alert--color,var(--now-messaging_label--primary--color,var(--now-color_text--primary,var(--now-color--neutral-18,22,27,28)))));
    border-radius: var(--now-alert--border-radius,var(--now-messaging--border-radius,.25rem));
    border-style: solid;
    border-width: var(--now-alert--border-width,var(--now-messaging--border-width,1px));
    h3 {
    	margin: 10px 10px 5px !important;
	}
    p {
    	margin: 5px 10px 10px;
	}
}

.navbar-inverse {
  .navbar-header .navbar-nav, .sub-navbar .navbar-nav {
		> li > a {
    		&:hover {
        		background-color: white;
        	    color: black;
			}
	        &:focus {
        		background-color: white;
        	    color: black;
			}
		}
    	.navbar-right .open .dropdown-menu {
    		> li > a {
	    		&:hover {
        			background-color: white;
        	    	color: black;
				}
	        	&:focus {
	        		background-color: white;
	        	    color: black;
				}
			}
		}
	    .desktop-headersearch-icon {
		    &:hover {
	        	background-color: white;
	            color: black;
			}
			&:focus {
       			background-color: white;
            	color: black;
			}
		}
	}
}

.kb-article-wrapper {
	.kb-mobile {
    	.kb-panel-heading, .kb-wrapper {
			color: black;
		}
	}
}

.technicalTemplate li:last-child {
	padding-bottom: 10px;
}

.scrub-footer {
    .sf-main {
    	.sf-logo-container, .sf-logo-container > * {
			align-content: center;
            display: inline-block;
          	text-align: center;
          	display: inline-block !important;
		    /*padding: initial !important;*/
	        .sf-logo {
                max-height: 4rem !important;
				margin: .5rem .8rem .5rem .5rem;
			}
		    .sf-logo-content {
	            vertical-align: middle;
              	padding: initial !important;
            }
		}
        .sf-links-container .masonry-root .sf-menu.masonry-cell {
        	/*border-left: .2rem solid #555555;*/
            .sf-link:hover {
            	background-color: white;
                a.sitemap-link {
                	color: black;
                    &:hover {
                    	color: blue;
                        text-decoration: underline;
                        cursor: pointer;
                    }
				}
            }
        }
    }
    .sf-bottom {
        .sf-bottom-left {
            .sf-logo-container, .sf-logo-container > * {
                display: inline-block;
                padding: initial;
                .sf-logo {
                    max-height: 4rem !important;
                    margin: .5rem .8rem .5rem .5rem;
                }
                .sf-logo-content {
                    vertical-align: middle;
                }
            }
        }
        .sf-bottom-right {
            margin: auto !important;

            .sf-bottom-links .sf-bottom-link:hover {
                background-color: white;

                a.footer-link {
                    color: black;

                    &:hover {
                        color: blue;
                        text-decoration: underline
                    }
                }
            }
            .sf-social-icons .sf-social-icon:hover {
                background-color: white;
                a.social-icon {
                    color: black;
                    &:hover {
                        color: blue;
                    }
                }
            }
        }
    }
}

@media screen and (max-width: 635px) {
    #mobile-menu-items-modal {
      .close-modal-button {
        > span {
          &:hover, &:focus {
            background-color: white;
            color: black;
            > svg {
            	stroke: black;
            	stroke-width: 2;
        	}
          }
        }
      }
      .mobile-menu-modal-list {
          .user-profile-menu-item, .mobile-list-item, .navbar-nav .header-menu-item {
            &:hover {
              background-color: white;
              > a {
                color: black;
                > .avatar-username, > .fa, > span{
                  color: black;
                }
              }
            }
          }
      }
  }
  .v5cf9e3234305ce107b228dc226b8f2a2 .scrub-footer {
        .sf-main {

            .sf-logo-container,
            .sf-logo-container>* {
