                }

                .sf-logo-content {
                    vertical-align: middle;
                    padding: initial;
                }
            }

            .sf-links-container {
            	padding-left: initial !important;
            	.masonry-root .sf-menu.masonry-cell {
                	/*border-top: .2rem solid #555555;*/
                	&:first-child {
                    	border-left: none;
					}
                }
            }
        }

        &:has(.sf-main) {
            .sf-bottom {
                .sf-bottom-left {
                    border-bottom: none;
                }
            }
        }

        &:not(:has(.sf-main)) {
            .sf-bottom {
                .sf-bottom-left {
                    border-bottom: .1rem solid black;
                }
            }
        }

        .sf-bottom {
            .sf-bottom-left {

                .sf-logo-container,
                .sf-logo-container>* {
                    display: inline-block;
                    padding: initial;
                    text-align: center;

                    .sf-logo {
                        max-height: 4rem !important;
                        margin: .5rem .8rem .5rem .5rem;
                    }

                    .sf-logo-content {
                        vertical-align: middle;
                    }
                }
            }

            .sf-bottom-right {
                padding-bottom: initial !important;
                padding-left: .8rem !important;

                .sf-bottom-links {
                    align-self: center;

                    .sf-bottom-link:hover {
                        background-color: white;

                        a.footer-link {
                            color: black;

                            &:hover {
                                color: blue;
                                text-decoration: underline
                            }
                        }
                    }
                }

                .sf-social-icons {
                    align-self: center;

                    .sf-social-icon:hover {
                        background-color: white;

                        a.social-icon {
                            color: black;

                            &:hover {
                                color: blue;
                            }
                        }
                    }
                }

                .sf-copyright {
                    align-self: center;
                }
            }
        }
    }
}
